A form uses this JavaScript validation function:
function check(age) {
    if (age == "") {
        return "Required";
    }
    if (isNaN(age)) {
        return "Not a number";
    }
    if (age < 16 || age > 99) {
        return "Out of range";
    }
    return "OK";
}
What does check("") return?
